export function lensPose(p){const edge=phase(p,.15,.48),detail=phase(p,.48,.72);return {x:lerp(lerp(170,279,edge),340,detail),y:lerp(210,243.75,detail),radius:68,zoom:1.8};}
export function unboxingPose(p){const open=phase(p,.1,.3),lift=phase(p,.38,.57),aside=phase(p,.59,.75),lower=phase(p,.77,.88);return {open,lift,aside,lower,x:lerp(267,454,aside),y:lerp(lerp(282,100,lift),283.4,lower),scale:.9,floor:350};}
function blendColor(a,b,t){return '#'+[1,3,5].map(i=>Math.round(lerp(parseInt(a.slice(i,i+2),16),parseInt(b.slice(i,i+2),16),t)).toString(16).padStart(2,'0')).join('');}
function polygon(c,points,color,stroke=C.ink){c.beginPath();points.forEach(([x,y],k)=>k?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fillStyle=color;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=1.6;c.stroke();}}
